      "title": "Jukebox hiển thị & 'phát ảo' danh sách nhạc mẫu dù không có file âm thanh trên ổ đĩa",
      "priority": "P1",
      "status": "done",
      "fixed_date": "24/11/2026 11:57",
      "ota_version": "v2026.11.24.01",
      "summary": "Quán không có file nhạc (.mp3/.wav/.flac) trong thư mục assets/media/ nhưng Kho nhạc vẫn hiện 6 bài mẫu (Baby Blue, Yesterday Once More, Trouble Is A Friend...) gắn nhãn 'Offline', hàng đợi vẫn hiện bài mẫu, vẫn bấm '+ Phát' được và thanh phát nhạc vẫn hiển thị trạng thái 'Đang phát / Tạm Dừng' (00:00) dù audio 404 không kêu gì.",
      "principle": "Single Source of Truth theo file vật lý trên ổ đĩa: Không seed bài hát/hàng đợi ảo nếu không có file thật; Backend xác thực std::filesystem::exists() cho mọi bài Offline khi liệt kê/quét/yêu cầu/phát; JukeboxEngine khi gặp lỗi 404/MEDIA_ERR phải dừng sạch trạng thái phát, báo cảnh báo rõ ràng và chống vòng lặp skip vô tận.",
      "issue_proposal": "Phát hiện 4 nguyên nhân gốc nối tiếp:\n1) Hardcode seed dữ liệu ảo (modules/mod_media_stream/mod_media_stream.cpp:150-197): Khi bảng media_tracks / media_jukebox_queue trống, DLL tự INSERT 6 bài mẫu + 3 dòng hàng đợi ('Baby Blue', '74 - 75', 'Yesterday Once More') mà KHÔNG kiểm tra file assets/media/*.mp3 có tồn tại thật hay không.\n2) Backend không xác thực file vật lý (slave/src/slave_handlers.cpp:9179-9255 & mod_media_stream.cpp:241-325): GET /api/media/tracks không trả cờ file_exists và không lọc bài mất file; POST /api/media/tracks/rescan chỉ biết thêm file mới mà không dọn/đánh dấu bài mất file; GET /api/media/jukebox/status & request/skip chỉ check file_path.empty() chứ không check std::filesystem::exists().\n3) Frontend gắn nhãn 'Offline' sai sự thật & vẫn cho bấm '+ Phát' (admin_media_dsp.js:565-595, pos-jukebox.js, customer_app.js): Không có cờ file_exists nên UI vẫn hiện badge 'Offline' và mở nút '+ Phát', khách QR cũng chọn nhầm bài ma.\n4) JukeboxEngine phát ảo khi audio 404 (slave/web/assets/js/jukebox-engine.js:76-127, 334-370): Sự kiện audio 'error' chỉ console.warn âm thầm, không đặt isPlaying=false, không hiển thị thông báo 'Thiếu file nhạc', khiến nút vẫn hiện 'Tạm Dừng' (00:00) hoặc lặp skip vô tận nếu cả hàng đợi đều thiếu file.\n\nĐề xuất xử lý đồng bộ:\n- Bỏ seed bài hát & hàng đợi ảo khi không có file thật trên đĩa (chỉ seed nếu file tồn tại thật; khi khởi động/rescan tự dọn các dòng hàng đợi & đánh dấu file_exists=0 cho bài mất file).\n- GET /api/media/tracks bổ sung trường file_exists (boolean) theo std::filesystem::exists() (hoặc ẩn hẳn bài mất file với trang khách customer.html?playable_only=1); POST /api/media/tracks/rescan vừa nạp file mới vừa dọn/đánh dấu bài mất file (kèm báo cáo số bài đã dọn).\n- POST /api/media/jukebox/request & skip từ chối (HTTP 400/404) nếu bài local không tồn tại trên đĩa và tự bỏ qua bài mất file khi tìm bài kế tiếp.\n- UI Admin/POS: bài thiếu file hiển thị badge đỏ 'Thiếu file' + khóa nút '+ Phát' (chỉ cho Xóa/Tải lại); nếu kho nhạc trống hiển thị hướng dẫn 'Chưa có file nhạc — nhấn Tải Nhạc hoặc thêm từ YouTube'.\n- JukeboxEngine: khi audio bắn lỗi 404/decode -> set isPlaying=false, xóa intent 'playing', bắn sự kiện/toast cảnh báo rõ ràng, và giới hạn số lần auto-skip liên tiếp (tối đa 3 bài) để không lặp vô tận.",
      "test_steps": "1) Xóa toàn bộ file .mp3 trong assets/media/ rồi khởi động lại Slave (hoặc bấm nút 'Quét' trong Kho nhạc).\n2) Xác nhận Kho nhạc báo trống / bài mất file gắn badge đỏ 'Thiếu file' và không cho bấm '+ Phát'; khách tại customer.html không thấy bài ảo.\n3) Xác nhận khu vực 'Đang phát hiện tại' hiển thị 'Chưa có bài hát nào đang phát', nút ở trạng thái 'Phát' (không bị kẹt 'Tạm Dừng' ở 00:00).\n4) Thử bấm Phát khi 1 bài bị xóa file đột ngột -> JukeboxEngine dừng sạch, báo Toast 'Không tìm thấy file nhạc trên máy chủ' và không treo vòng lặp skip.\n5) Tải lên 1 file .mp3 thật -> bấm Phát -> phát âm thanh bình thường.",
