      "principle": "Trình tự 3 vùng cố định (1 dòng h=54px): [TRÁI: Logo + Tên quán + Badge vai trò + Trạng thái] | [GIỮA: Tab chuyển màn hình & Nút nghiệp vụ trang] | [PHẢI CỐ ĐỊNH: VI/EN -> Sáng/Tối -> Huy hiệu Tài khoản -> Đăng xuất (Sign Out) ngoài cùng bên phải].\nPhân quyền hiển thị & luồng Quay lại theo Role:\n1. ADMIN (admin): Thấy toàn bộ tab ([POS], [Bếp], [Phục vụ], [Đơn Online], [Chấm công], [Jukebox], [Tắt Server] ở admin.html). Khi sang POS/Bếp/Phục vụ/Online, Vùng Giữa có nút [← Quản Trị] và bấm vào thẻ [ADMIN] ở Vùng Phải cũng quay về admin.html.\n2. THU NGÂN (cashier): Ở POS thấy Nhóm chuyển trang ([Bếp], [Phục vụ], [Đơn Online]) + Nhóm Quầy ([Giao Ca], [Lịch Sử], [Thống Kê], [Mở Két], [Chấm Công]) + Tiện ích ([Làm mới], [QR], [Jukebox]); KHÔNG thấy Admin. Khi sang Bếp/Phục vụ/Online, Vùng Giữa hiện [← Quay lại POS] để về index.html.\n3. BẾP (kitchen): CHỈ thấy [Chuông], [Món Khóa], [Làm mới] trên kitchen.html; TUYỆT ĐỐI ẨN nút POS/Order/Online/Admin; chỉ có [Đăng xuất] ở Vùng Phải.\n4. PHỤC VỤ (waiter): CHỈ thấy [Chuông], [QR] trên order.html; TUYỆT ĐỐI ẨN nút POS/Bếp/Online/Admin; chỉ có [Đăng xuất] ở Vùng Phải.\n5. KHÁCH (customer): CHỈ thấy menu gọi món trên customer.html, Vùng Phải chỉ có [VI/EN] + [Sáng/Tối] + [Tài khoản khách].",
